/// The video codec of a stream. H.264 everywhere (hardware of any vendor, OpenH264 on the CPU); AV1 where the GPU
/// has an AV1 encoder (sending) and Windows has an AV1 decoder (receiving: the AV1 Video Extension).
pub use queqiao_core::protocol::VideoCodec;

/// Whether `data` (one frame as the encoder made it) starts a decodable stream: an H.264 IDR picture, or an AV1
/// temporal unit with a sequence header (encoders send one with every keyframe).
pub fn is_keyframe(codec: VideoCodec, data: &[u8]) -> bool {
    match codec {
        VideoCodec::H264 => nal_types(data).contains(&5),
        VideoCodec::Av1 => av1_obu_types(data).contains(&1),
    }
}

/// The OBU types in an AV1 temporal unit (low-overhead format: each OBU with its size), in order.
pub fn av1_obu_types(data: &[u8]) -> Vec<u8> {
    let mut types = Vec::new();
    let mut at = 0usize;
    while at < data.len() {
        let header = data[at];
        let kind = (header >> 3) & 0x0F;
        let extension = header & 0x04 != 0;
        let has_size = header & 0x02 != 0;
        types.push(kind);
        at += 1 + usize::from(extension);
        if !has_size {
            break;
        }
        // LEB128 size.
        let mut size = 0usize;
        for byte in 0..8 {
            let Some(&value) = data.get(at) else {
                return types;
            };
            at += 1;
            size |= usize::from(value & 0x7F) << (7 * byte);
            if value & 0x80 == 0 {
                break;
            }
        }
        at = at.saturating_add(size);
    }
    types
}

/// Whether this PC can encode `codec` (H.264 always: OpenH264 is built in; other codecs on `device`'s GPU, through
/// Media Foundation). A registered encoder is not enough: one is opened (1280x720 at 60 fps) and closed again. Measured
/// 2026-11-22 on a 12th-gen Intel Iris Xe: its driver registers "Intel Hardware Accelerated AV1 Encoder MFT", which
/// refuses every format with E_FAIL, as that GPU has no AV1 encoding hardware. Takes about 30 ms where it works.
pub fn can_encode(
    codec: VideoCodec,
    device: &windows::Win32::Graphics::Direct3D11::ID3D11Device,
) -> bool {
    if codec == VideoCodec::H264 {
        return true;
    }
    let config = EncoderConfig {
        codec,
        ..EncoderConfig::for_screen(1280, 720, 60)
    };
    mf::MfEncoder::open(device, &config, &mut Vec::new()).is_some()
}

/// Whether this PC can decode `codec` (H.264 always: OpenH264 is built in).
pub fn can_decode(codec: VideoCodec) -> bool {
    codec == VideoCodec::H264 || mf_decode::has_decoder(codec)
}

/// Whether `device`'s GPU decodes AV1 itself (Direct3D's AV1 decoder profile): without it Windows' AV1 decoder
/// works on the CPU, too slow for a large screen at 60 frames per second.
pub fn av1_decodes_on_gpu(device: &windows::Win32::Graphics::Direct3D11::ID3D11Device) -> bool {
    use windows::Win32::Graphics::Direct3D11::{
        D3D11_DECODER_PROFILE_AV1_VLD_PROFILE0, ID3D11VideoDevice,
    };
    use windows::core::Interface;
    let Ok(video) = device.cast::<ID3D11VideoDevice>() else {
        return false;
    };
    let count = unsafe { video.GetVideoDecoderProfileCount() };
    (0..count).any(|index| {
        unsafe { video.GetVideoDecoderProfile(index) }
            .is_ok_and(|profile| profile == D3D11_DECODER_PROFILE_AV1_VLD_PROFILE0)
    })
}

/// Encode sizes to try for a screen, largest first: the screen itself (rounded down to even numbers, as
/// NV12 needs), then the same picture scaled down to fit common encoder limits (4096, 4K, 1440p, 1080p,
/// 720p boxes, turned for portrait screens). Never larger than the screen; the aspect ratio is kept.
pub fn candidate_sizes(width: u32, height: u32) -> Vec<(u32, u32)> {
    let boxes = [
        (u32::MAX, u32::MAX),
        (4096, 4096),
        (3840, 2160),
        (2560, 1440),
        (1920, 1080),
        (1280, 720),
    ];
    let mut sizes = Vec::new();
    for (long, short) in boxes {
        let (max_w, max_h) = if height > width {
            (short, long)
        } else {
            (long, short)
        };
        // Whole numbers: the side that meets the box is the box's, the other in proportion. (In floating point
        // 1400 x 720/1400 came out as 719.99 and the 16:10 laptop got 1152x718 for a 720 picture.)
        let (width_wide, height_wide) = (u64::from(width.max(1)), u64::from(height.max(1)));
        let (w, h) = if width <= max_w && height <= max_h {
            (width, height)
        } else if u64::from(max_w) * height_wide <= u64::from(max_h) * width_wide {
            // The width meets the box first.
            (max_w, (height_wide * u64::from(max_w) / width_wide) as u32)
        } else {
            ((width_wide * u64::from(max_h) / height_wide) as u32, max_h)
        };
        let (w, h) = (w & !1, h & !1);
        if w >= 2 && h >= 2 && !sizes.contains(&(w, h)) {
            sizes.push((w, h));
        }
    }
    sizes
}

/// NAL unit types in an Annex-B H.264 stream, in order (7 = SPS, 8 = PPS, 5 = IDR slice, 1 = other slice,
/// 6 = SEI, 9 = access unit delimiter).
pub fn nal_types(data: &[u8]) -> Vec<u8> {
    data.windows(4)
        .filter(|w| w[..3] == [0, 0, 1])
        .map(|w| w[3] & 0x1F)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn av1_keyframes_carry_a_sequence_header() {
        // Temporal delimiter (type 2, size 0), sequence header (type 1, 3 bytes), frame (type 6, 2 bytes).
        let key = [0x12, 0x00, 0x0A, 0x03, 1, 2, 3, 0x32, 0x02, 9, 9];
        assert_eq!(av1_obu_types(&key), vec![2, 1, 6]);
        assert!(is_keyframe(VideoCodec::Av1, &key));
        // A frame alone (after a temporal delimiter): not a keyframe.
        let delta = [0x12, 0x00, 0x32, 0x02, 9, 9];
        assert_eq!(av1_obu_types(&delta), vec![2, 6]);
        assert!(!is_keyframe(VideoCodec::Av1, &delta));
        // A size over 127 (two LEB128 bytes), and data cut short: no panic.
        let mut long = vec![0x32, 0x80, 0x01];
        long.extend(vec![0u8; 128]);
        long.extend([0x0A, 0x00]);
        assert_eq!(av1_obu_types(&long), vec![6, 1]);
        assert_eq!(av1_obu_types(&[0x32, 0xFF]), vec![6]);
        assert!(av1_obu_types(&[]).is_empty());
    }

    #[test]
    fn finds_nal_types_after_3_and_4_byte_start_codes() {
        let stream = [
            0, 0, 0, 1, 0x67, 0x42, 0, 0, 0, 1, 0x68, 0xCE, 0, 0, 1, 0x65, 0x88,
        ];
        assert_eq!(nal_types(&stream), vec![7, 8, 5]);
    }

    #[test]
    fn candidate_sizes_cover_common_screens() {
        assert_eq!(
            candidate_sizes(2560, 1440),
            vec![(2560, 1440), (1920, 1080), (1280, 720)]
        );
        // Super-wide 5120x1440: the full width is beyond many H.264 encoders, so smaller sizes follow.
        assert_eq!(
            candidate_sizes(5120, 1440)[..2],
            [(5120, 1440), (4096, 1152)]
        );
        // Odd sizes (some virtual machines) are rounded down to even.
        assert_eq!(candidate_sizes(1365, 767)[0], (1364, 766));
        // Portrait screens keep their orientation.
        assert_eq!(candidate_sizes(1440, 2560)[1], (1080, 1920));
        // Small screens are never scaled up.
        assert_eq!(candidate_sizes(800, 600), vec![(800, 600)]);
        // 16:10 into the 720p box: exactly 720 lines (it was 718), and the same turned.
        assert!(candidate_sizes(2240, 1400).contains(&(1152, 720)));
        assert!(candidate_sizes(1920, 1200).contains(&(1152, 720)));
        assert!(candidate_sizes(1400, 2240).contains(&(720, 1152)));
        // The aspect ratio is kept: one side is within 2 pixels of the exact value for the other.
        for (width, height) in [
            (2240, 1400),
            (2560, 1600),
            (3000, 2000),
            (1366, 768),
            (3440, 1440),
        ] {
            for (w, h) in candidate_sizes(width, height) {
                let exact_h = f64::from(w) * f64::from(height) / f64::from(width);
                let exact_w = f64::from(h) * f64::from(width) / f64::from(height);
                let off = (f64::from(h) - exact_h)
                    .abs()
                    .min((f64::from(w) - exact_w).abs());
                assert!(off <= 2.0, "{width}x{height} -> {w}x{h}");
            }
        }
    }
}
